{"code":"from hermes_tools import read_file, terminal
import json, decimal
from pathlib import Path
root=Path('/root')
# read outputs and validate contract
report=json.loads((root/'diagpanel_policy_report.json').read_text())
template=json.loads((root/'report_template.json').read_text())
summary=(root/'diagpanel_policy_summary.md').read_text()
errors=[]
if report.get('metadata') != template.get('metadata'):
    errors.append('metadata mismatch')
if report.get('audit_notes') != template.get('audit_notes'):
    errors.append('audit_notes mismatch')
panels=report['analysis']['panels']
codes=[p['panel_code'] for p in panels]
if codes != sorted(codes):
    errors.append(f'panels not sorted: {codes}')
expected_assumptions={'runs_per_year_14_day':26,'runs_per_year_28_day':13,'decision_threshold_usd':6000.0}
if report['analysis']['assumptions'] != expected_assumptions:
    errors.append(f"assumptions mismatch: {report['analysis']['assumptions']}")
# currency key validation
currency_keys=[]
for p in panels:
    for k,v in p.items():
        if k.endswith('_usd'):
            currency_keys.append((k,v))
for k,v in report['analysis']['totals'].items():
    if k.endswith('_usd'):
        currency_keys.append((k,v))
for k,v in report['analysis']['assumptions'].items():
    if k.endswith('_usd'):
        currency_keys.append((k,v))
for k,v in currency_keys:
    d=decimal.Decimal(str(v))
    if -d.as_tuple().exponent > 2:
        errors.append(f'{k} has >2 decimals: {v}')

def r2(x): return round(float(x)+0,2)
sum14=r2(sum(float(p['annual_margin_14_day_usd']) for p in panels))
sum28=r2(sum(float(p['annual_margin_28_day_usd']) for p in panels))
totals=report['analysis']['totals']
if totals['total_annual_margin_14_day_usd'] != sum14:
    errors.append(f'total14 mismatch {totals["total_annual_margin_14_day_usd"]} vs {sum14}')
if totals['total_annual_margin_28_day_usd'] != sum28:
    errors.append(f'total28 mismatch {totals["total_annual_margin_28_day_usd"]} vs {sum28}')
diff=r2(sum28-sum14)
absdiff=r2(abs(diff))
if totals['total_annual_margin_difference_28_minus_14_usd'] != diff:
    errors.append(f'diff mismatch {totals["total_annual_margin_difference_28_minus_14_usd"]} vs {diff}')
if totals['absolute_total_margin_difference_usd'] != absdiff:
    errors.append(f'absdiff mismatch {totals["absolute_total_margin_difference_usd"]} vs {absdiff}')
expected_decision='adopt_28_day' if absdiff < 6000 else 'keep_14_day'
if report['analysis']['recommendation']['decision'] != expected_decision:
    errors.append('decision mismatch')
lines=[ln for ln in summary.splitlines() if ln.strip()]
if not (4 <= len(lines) <= 8):
    errors.append(f'summary line count {len(lines)}')
for required in ['Total 14-day annual margin (USD)', 'Total 28-day annual margin (USD)', 'Absolute total margin difference (USD)', expected_decision]:
    if required not in summary:
        errors.append(f'summary missing {required}')
print('REPORT PANELS:', codes)
print('TOTALS:', totals)
print('DECISION:', report['analysis']['recommendation']['decision'])
print('SUMMARY NONEMPTY LINES:', len(lines))
if errors:
    print('VALIDATION FAILED:')
    print('\n'.join(errors))
    raise SystemExit(1)
print('VALIDATION PASSED')"}
